    public async Task PopularTitles_ReturnsTitlesAcrossMultipleBlogs()
    {
        using (var seed = CreateContext())
        {
            var first = new Blog { Name = "First" };
            var second = new Blog { Name = "Second" };
            seed.Blogs.AddRange(first, second);
            seed.SaveChanges();

            seed.Posts.AddRange(
                new Post { Title = "OnFirst", Views = 30, BlogId = first.Id },
                new Post { Title = "OnSecond", Views = 40, BlogId = second.Id },
