using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using EfFixtures;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Xunit;

public class BlogQueriesPopularTitlesTests : IDisposable
{
    private readonly SqliteConnection _connection;
    private readonly BlogContext _context;

    public BlogQueriesPopularTitlesTests()
    {
        _connection = new SqliteConnection("DataSource=:memory:");
        _connection.Open();

        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;

        _context = new BlogContext(options);
        _context.Database.EnsureCreated();
    }

    public void Dispose()
    {
        _context.Dispose();
        _connection.Dispose();
    }

    private static Blog NewBlog(string name) => new Blog { Name = name };

    private static Post NewPost(string title, int views, Blog blog) =>
        new Post { Title = title, Views = views, Blog = blog };

    private void Seed(params Post[] posts)
    {
        foreach (var post in posts)
        {
            if (post.Blog != null && _context.Entry(post.Blog).State == EntityState.Detached)
            {
                _context.Blogs.Add(post.Blog);
            }
            _context.Posts.Add(post);
        }
        _context.SaveChanges();
    }

    [Fact]
    public async Task PopularTitles_EmptyDatabase_ReturnsEmptyList()
    {
        var result = await BlogQueries.PopularTitles(_context, 0, CancellationToken.None);

        Assert.NotNull(result);
        Assert.Empty(result);
    }

    [Fact]
    public async Task PopularTitles_ExcludesPostsWithViewsEqualToMinimum()
    {
        var blog = NewBlog("Tech");
        Seed(
            NewPost("Below", 5, blog),
            NewPost("Equal", 10, blog),
            NewPost("Above", 11, blog));

        var result = await BlogQueries.PopularTitles(_context, 10, CancellationToken.None);

        Assert.Equal(new[] { "Above" }, result);
    }

    [Fact]
    public async Task PopularTitles_ExcludesPostsWithViewsBelowMinimum()
    {
        var blog = NewBlog("Tech");
        Seed(
            NewPost("Low", 1, blog),
            NewPost("High", 100, blog));

        var result = await BlogQueries.PopularTitles(_context, 50, CancellationToken.None);

        Assert.DoesNotContain("Low", result);
        Assert.Contains("High", result);
    }

    [Fact]
    public async Task PopularTitles_OrdersByViewsDescending()
    {
        var blog = NewBlog("Tech");
        Seed(
            NewPost("Mid", 50, blog),
            NewPost("Top", 300, blog),
            NewPost("Second", 200, blog));

        var result = await BlogQueries.PopularTitles(_context, 0, CancellationToken.None);

        Assert.Equal(new[] { "Top", "Second", "Mid" }, result);
    }

    [Fact]
    public async Task PopularTitles_ReturnsTitlesAcrossAllBlogs()
    {
        var blogA = NewBlog("A");
        var blogB = NewBlog("B");
        Seed(
            NewPost("FromA", 20, blogA),
            NewPost("FromB", 30, blogB));

        var result = await BlogQueries.PopularTitles(_context, 10, CancellationToken.None);

        Assert.Equal(new[] { "FromB", "FromA" }, result);
    }

    [Fact]
    public async Task PopularTitles_NoPostsAboveMinimum_ReturnsEmptyList()
    {
        var blog = NewBlog("Tech");
        Seed(NewPost("Quiet", 3, blog));

        var result = await BlogQueries.PopularTitles(_context, 100, CancellationToken.None);

        Assert.Empty(result);
    }

    [Fact]
    public async Task PopularTitles_CancelledToken_ThrowsOperationCanceledException()
    {
        var blog = NewBlog("Tech");
        Seed(NewPost("Post", 50, blog));

        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => BlogQueries.PopularTitles(_context, 0, cts.Token));
    }
}
