    [Fact]
    public async Task ReturnsEmptyListWhenNoBlogsExist()
    {
        using var database = CreateContext();

        var result = await BlogQueries.TotalViewsPerBlog(database, CancellationToken.None);

        Assert.Empty(result);
    }

    [Fact]
    public async Task SumsPostViewsForEachBlog()
    {
        var alpha = new Blog { Name = "Alpha" };
        var beta = new Blog { Name = "Beta" };
        using (var seed = CreateContext())
        {
            seed.Blogs.AddRange(alpha, beta);
            seed.Posts.AddRange(
                new Post { Title = "A1", Views = 10, Blog = alpha },
                new Post { Title = "A2", Views = 5, Blog = alpha },
                new Post { Title = "B1", Views = 7, Blog = beta });
            seed.SaveChanges();
        }

        using var database = CreateContext();
        var result = await BlogQueries.TotalViewsPerBlog(database, CancellationToken.None);

        Assert.Equal(new[] { new BlogTotal("Alpha", 15), new BlogTotal("Beta", 7) }, result);
    }

    [Fact]
    public async Task OrdersResultsByBlogName()
    {
        var zeta = new Blog { Name = "Zeta" };
        var alpha = new Blog { Name = "Alpha" };
        using (var seed = CreateContext())
        {
            seed.Blogs.AddRange(zeta, alpha);
            seed.Posts.AddRange(
                new Post { Title = "Z1", Views = 1, Blog = zeta },
                new Post { Title = "A1", Views = 2, Blog = alpha });
            seed.SaveChanges();
        }

        using var database = CreateContext();
        var result = await BlogQueries.TotalViewsPerBlog(database, CancellationToken.None);

        Assert.Equal(new[] { new BlogTotal("Alpha", 2), new BlogTotal("Zeta", 1) }, result);
    }

    [Fact]
    public async Task BlogWithoutPostsHasZeroTotal()
    {
        using (var seed = CreateContext())
        {
            var empty = new Blog { Name = "Empty" };
            var solo = new Blog { Name = "Solo" };
            seed.Blogs.AddRange(empty, solo);
            seed.Posts.Add(new Post { Title = "S1", Views = 3, Blog = solo });
            seed.SaveChanges();
        }

        using var database = CreateContext();
        var result = await BlogQueries.TotalViewsPerBlog(database, CancellationToken.None);

        Assert.Equal(new[] { new BlogTotal("Empty", 0), new BlogTotal("Solo", 3) }, result);
    }

    [Fact]
    public async Task ContributorsDoNotInflateViewTotals()
    {
        using (var seed = CreateContext())
        {
            var gamma = new Blog { Name = "Gamma" };
            seed.Blogs.Add(gamma);
            seed.Posts.AddRange(
                new Post { Title = "G1", Views = 4, Blog = gamma },
                new Post { Title = "G2", Views = 6, Blog = gamma });
            seed.Contributors.AddRange(
                new Contributor { Name = "Ann", Blog = gamma },
                new Contributor { Name = "Ben", Blog = gamma },
                new Contributor { Name = "Cy", Blog = gamma });
            seed.SaveChanges();
        }

        using var database = CreateContext();
        var result = await BlogQueries.TotalViewsPerBlog(database, CancellationToken.None);

        Assert.Equal(new[] { new BlogTotal("Gamma", 10) }, result);
    }
