using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using EfFixtures;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Xunit;

public sealed class BlogQueriesTotalViewsPerBlogTests : IDisposable
{
    private readonly SqliteConnection _connection;
    private readonly BlogContext _database;

    public BlogQueriesTotalViewsPerBlogTests()
    {
        _connection = new SqliteConnection("DataSource=:memory:");
        _connection.Open();

        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;

        _database = new BlogContext(options);
        _database.Database.EnsureCreated();
    }

    public void Dispose()
    {
        _database.Dispose();
        _connection.Dispose();
    }

    [Fact]
    public async Task ReturnsEmptyListWhenThereAreNoBlogs()
    {
        var totals = await BlogQueries.TotalViewsPerBlog(_database, CancellationToken.None);

        Assert.Empty(totals);
    }

    [Fact]
    public async Task ReturnsZeroTotalForBlogWithoutPosts()
    {
        await AddBlogAsync("Empty Blog");

        var totals = await BlogQueries.TotalViewsPerBlog(_database, CancellationToken.None);

        Assert.Equal(new[] { new BlogTotal("Empty Blog", 0) }, totals);
    }

    [Fact]
    public async Task SumsViewsOfEachBlogsOwnPosts()
    {
        var alpha = await AddBlogAsync("Alpha");
        var beta = await AddBlogAsync("Beta");
        await AddPostsAsync(alpha, 10, 20);
        await AddPostsAsync(beta, 5);

        var totals = await BlogQueries.TotalViewsPerBlog(_database, CancellationToken.None);

        Assert.Equal(
            new[] { new BlogTotal("Alpha", 30), new BlogTotal("Beta", 5) },
            totals);
    }

    [Fact]
    public async Task OrdersResultsByBlogName()
    {
        var charlie = await AddBlogAsync("Charlie");
        var alpha = await AddBlogAsync("Alpha");
        var bravo = await AddBlogAsync("Bravo");
        await AddPostsAsync(charlie, 1);
        await AddPostsAsync(alpha, 2);
        await AddPostsAsync(bravo, 3);

        var totals = await BlogQueries.TotalViewsPerBlog(_database, CancellationToken.None);

        Assert.Equal(
            new[] { new BlogTotal("Alpha", 2), new BlogTotal("Bravo", 3), new BlogTotal("Charlie", 1) },
            totals);
    }

    [Fact]
    public async Task IncludesZeroViewPostsInTotal()
    {
        var blog = await AddBlogAsync("Quiet Blog");
        await AddPostsAsync(blog, 0, 0);

        var totals = await BlogQueries.TotalViewsPerBlog(_database, CancellationToken.None);

        Assert.Equal(new[] { new BlogTotal("Quiet Blog", 0) }, totals);
    }

    [Fact]
    public async Task ContributorsDoNotAffectViewTotals()
    {
        var blog = await AddBlogAsync("Team Blog");
        await AddPostsAsync(blog, 10, 20);
        _database.Contributors.Add(new Contributor { Name = "Ann", BlogId = blog.Id });
        _database.Contributors.Add(new Contributor { Name = "Ben", BlogId = blog.Id });
        await _database.SaveChangesAsync();

        var totals = await BlogQueries.TotalViewsPerBlog(_database, CancellationToken.None);

        Assert.Equal(new[] { new BlogTotal("Team Blog", 30) }, totals);
    }

    [Fact]
    public async Task DoesNotCountPostsBelongingToOtherBlogs()
    {
        var first = await AddBlogAsync("First");
        var second = await AddBlogAsync("Second");
        await AddPostsAsync(first, 7);
        await AddPostsAsync(second, 100);

        var totals = await BlogQueries.TotalViewsPerBlog(_database, CancellationToken.None);

        Assert.Equal(
            new[] { new BlogTotal("First", 7), new BlogTotal("Second", 100) },
            totals);
    }

    private async Task<Blog> AddBlogAsync(string name)
    {
        var blog = new Blog { Name = name };
        _database.Blogs.Add(blog);
        await _database.SaveChangesAsync();
        return blog;
    }

    private async Task AddPostsAsync(Blog blog, params int[] views)
    {
        for (var i = 0; i < views.Length; i++)
        {
            _database.Posts.Add(new Post
            {
                Title = $"{blog.Name} post {i + 1}",
                Views = views[i],
                BlogId = blog.Id
            });
        }
        await _database.SaveChangesAsync();
    }
}
