        {
            blog.Posts.Add(new Post { Title = title, Views = views });
        }
        context.Blogs.Add(blog);
        context.SaveChanges();
    }

    private async Task<List<string>> Run(int minViews, CancellationToken token = default)
    {
        using var context = _fixture.CreateContext();
        return await BlogQueries.PopularTitles(context, minViews, token);
    }

    [Fact]
    public async Task ReturnsEmptyWhenNoPosts()
    {
        var result = await Run(0);

        Assert.Empty(result);
    }

    [Fact]
    public async Task ReturnsEmptyWhenNoPostExceedsThreshold()
