        var result = await Run(10);

        Assert.Equal(new[] { "High", "Mid", "Low" }, result);
    }

    [Fact]
    public async Task ThresholdIsExclusive()
    {
        Seed(("AtThreshold", 100), ("Above", 101), ("Below", 99));

        var result = await Run(100);

        Assert.Equal(new[] { "Above" }, result);
    }

    [Fact]
    public async Task IncludesPostsFromAllBlogs()
    {
        using (var context = _fixture.CreateContext())
