            {
                Name = "Beta",
                Posts = { NewPost("B1", 7) }
            });
        });

        var result = await RunAsync(db);

        Assert.Equal(
            new[] { new BlogTotal("Alpha", 35), new BlogTotal("Beta", 7) },
            result);
    }

    [Fact]
    public async Task BlogWithNoPostsHasZeroTotal()
    {
        using var db = new SqliteBlogDatabase();
        db.Seed(context => context.Blogs.Add(new Blog { Name = "Empty" }));

        var result = await RunAsync(db);

        var total = Assert.Single(result);
        Assert.Equal(new BlogTotal("Empty", 0), total);
    }

    [Fact]
    public async Task BlogWithOnlyZeroViewPostsHasZeroTotal()
    {
        using var db = new SqliteBlogDatabase();
        db.Seed(context => context.Blogs.Add(new Blog
        {
            Name = "Quiet",
            Posts = { NewPost("Q1", 0), NewPost("Q2", 0) }
        }));

        var result = await RunAsync(db);

        Assert.Equal(new BlogTotal("Quiet", 0), Assert.Single(result));
    }

