    public async Task ResultsAreOrderedByBlogName()
    {
        using var db = new SqliteBlogDatabase();
        db.Seed(context =>
        {
            context.Blogs.Add(new Blog { Name = "Charlie", Posts = { NewPost("C", 3) } });
            context.Blogs.Add(new Blog { Name = "Alpha", Posts = { NewPost("A", 1) } });
            context.Blogs.Add(new Blog { Name = "Bravo", Posts = { NewPost("B", 2) } });
        });

        var result = await RunAsync(db);

        Assert.Equal(new[] { "Alpha", "Bravo", "Charlie" }, result.Select(r => r.BlogName).ToArray());
    }

    [Fact]
    public async Task DoesNotMixPostsFromDifferentBlogs()
    {
        using var db = new SqliteBlogDatabase();
        db.Seed(context =>
        {
            context.Blogs.Add(new Blog { Name = "One", Posts = { NewPost("1", 100) } });
            context.Blogs.Add(new Blog { Name = "Two", Posts = { NewPost("2", 1) } });
        });

        var result = await RunAsync(db);

        Assert.Equal(100, result.Single(r => r.BlogName == "One").TotalViews);
        Assert.Equal(1, result.Single(r => r.BlogName == "Two").TotalViews);
    }

