    {
        await _context.DisposeAsync();
        await _connection.DisposeAsync();
    }

    private async Task SeedAsync(params Post[] posts)
    {
        _context.Posts.AddRange(posts);
        await _context.SaveChangesAsync();
    }

    private static Post Post(string title, int views, int blogId = 1) =>
        new Post { Title = title, Views = views, BlogId = blogId };

    [Fact]
    public async Task ReturnsOnlyPostsAboveMinViews()
    {
        await SeedAsync(
            Post("low", 5),
            Post("borderline", 10),
