        Assert.Equal(new List<string> { "high" }, titles);
    }

    [Fact]
    public async Task OrdersTitlesByViewsDescending()
    {
        await SeedAsync(
            Post("medium", 20),
            Post("highest", 99),
            Post("lowest", 11));

        var titles = await BlogQueries.PopularTitles(_context, 10, CancellationToken.None);

        Assert.Equal(new List<string> { "highest", "medium", "lowest" }, titles);
    }

    [Fact]
    public async Task ReturnsEmptyListWhenNoPostsQualify()
    {
        await SeedAsync(Post("quiet", 1), Post("calm", 3));

        var titles = await BlogQueries.PopularTitles(_context, 100, CancellationToken.None);

        Assert.Empty(titles);
    }

    [Fact]
    public async Task ReturnsEmptyListWhenNoPostsExist()
    {
        var titles = await BlogQueries.PopularTitles(_context, 0, CancellationToken.None);

        Assert.Empty(titles);
    }

    [Fact]
    public async Task IncludesPostsFromAllBlogs()
    {
        var blogA = new Blog { Id = 1, Name = "A", Posts = new List<Post>(), Contributors = new List<Contributor>() };
        var blogB = new Blog { Id = 2, Name = "B", Posts = new List<Post>(), Contributors = new List<Contributor>() };
        _context.Blogs.AddRange(blogA, blogB);
        await _context.SaveChangesAsync();

        await SeedAsync(
            Post("from-a", 30, blogId: 1),
            Post("from-b", 40, blogId: 2),
            Post("ignored", 1, blogId: 2));

        var titles = await BlogQueries.PopularTitles(_context, 10, CancellationToken.None);

        Assert.Equal(new List<string> { "from-b", "from-a" }, titles);
    }

    [Fact]
    public async Task HonorsCancellationToken()
    {
        await SeedAsync(Post("post", 10));

        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => BlogQueries.PopularTitles(_context, 0, cts.Token));
    }
