    }

    private static SqliteConnection NewConnection() =>
        new SqliteConnection("Data Source=:memory:");

    private static async Task<BlogContext> SeededContextAsync()
    {
        var connection = NewConnection();
        var context = await CreateContextAsync(connection);
        context.Blogs.AddRange(
            new Blog
            {
                Id = 1,
                Name = "Zeta",
                Posts = new List<Post>
                {
                    new Post { Id = 1, Title = "Z1", Views = 10, BlogId = 1 },
                    new Post { Id = 2, Title = "Z2", Views = 5, BlogId = 1 },
                },
                Contributors = new List<Contributor>()
            },
            new Blog
            {
                Id = 2,
                Name = "Alpha",
                Posts = new List<Post>
                {
                    new Post { Id = 3, Title = "A1", Views = 100, BlogId = 2 },
                },
                Contributors = new List<Contributor>()
            },
            new Blog
            {
                Id = 3,
                Name = "Mid",
                Posts = new List<Post>(),
                Contributors = new List<Contributor>()
            });
        await context.SaveChangesAsync();
        return context;
    }

    [Fact]
    public async Task TotalViewsPerBlog_SumsViewsPerBlog_AndOrdersByName()
    {
        await using var context = await SeededContextAsync();

        var result = await BlogQueries.TotalViewsPerBlog(context, CancellationToken.None);

        Assert.Equal(3, result.Count);
        Assert.Equal(new BlogTotal("Alpha", 100), result[0]);
        Assert.Equal(new BlogTotal("Mid", 0), result[1]);
        Assert.Equal(new BlogTotal("Zeta", 15), result[2]);
    }

    [Fact]
    public async Task TotalViewsPerBlog_EmptyDatabase_ReturnsEmptyList()
    {
        await using var context = await CreateContextAsync(NewConnection());

        var result = await BlogQueries.TotalViewsPerBlog(context, CancellationToken.None);

        Assert.Empty(result);
    }

    [Fact]
    public async Task TotalViewsPerBlog_IgnoresContributorsAndOtherBlogPosts()
    {
